/**
 * Free Fire Prime System - All-in-One Zero-Load CDN Web Component
 * 100% Transparent Background - Pure Client-Side Zero Server Load
 */
(function(window, document) {
  'use strict';

  // 1. Auto-inject Transparent CSS Stylesheet into <head>
  const css = "/**\n * Free Fire Prime System - Refined Transparent Badge VFX\n * 100% Organic, Natural In-Game Emission (With Right-to-Upward Ascending Energy Stream)\n */\n\n/* Main Badge Container */\n.ff-prime-badge-wrap {\n  position: relative;\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  background: transparent !important;\n  user-select: none;\n  vertical-align: middle;\n  overflow: visible;\n}\n\n/* Scalable sizing presets */\n.ff-prime-sm { width: 42px; height: 42px; }\n.ff-prime-md { width: 72px; height: 72px; }\n.ff-prime-lg { width: 140px; height: 140px; }\n.ff-prime-xl { width: 220px; height: 220px; }\n\n/* The Badge Image (Contour Drop-Shadows make glow emit directly from the badge) */\n.ff-prime-badge-wrap .ff-badge-img {\n  width: 100%;\n  height: 100%;\n  object-fit: contain;\n  position: relative;\n  z-index: 5;\n  background: transparent;\n  pointer-events: none;\n  transition: transform 0.3s ease, filter 0.3s ease;\n}\n\n/* Canvas Particle Layer (100% Transparent, Micro-Embers) */\n.ff-prime-badge-wrap .ff-particle-canvas {\n  position: absolute;\n  top: -40%;\n  left: -40%;\n  width: 180%;\n  height: 180%;\n  pointer-events: none;\n  background: transparent !important;\n  z-index: 4;\n}\n\n/* Core Aura Glow (Tightly anchored behind badge silhouette) */\n.ff-prime-badge-wrap .ff-core-aura {\n  position: absolute;\n  width: 95%;\n  height: 95%;\n  border-radius: 50%;\n  pointer-events: none;\n  filter: blur(14px);\n  opacity: 0;\n  z-index: 2;\n  background: transparent;\n  transition: all 0.4s ease;\n}\n\n/* Organic Center Gem Twinkle */\n.ff-prime-badge-wrap .ff-gem-glint {\n  position: absolute;\n  top: 48%;\n  left: 50%;\n  width: 38%;\n  height: 38%;\n  transform: translate(-50%, -50%) scale(0);\n  background: radial-gradient(circle, rgba(255, 255, 255, 0.95) 0%, rgba(255, 230, 130, 0.7) 25%, rgba(255, 183, 3, 0.25) 55%, transparent 70%);\n  border-radius: 50%;\n  pointer-events: none;\n  z-index: 7;\n  opacity: 0;\n  mix-blend-mode: screen;\n}\n\n/* ========================================================\n   \u2605 ASCENDING GOLDEN ENERGY STREAM (\u09a1\u09be\u09a8 \u09a5\u09c7\u0995\u09c7 \u0989\u09aa\u09b0\u09c7\u09b0 \u09a6\u09bf\u0995\u09c7 \u09ab\u09cd\u09b2\u09cb) \u2605\n   ======================================================== */\n.ff-prime-badge-wrap .ff-energy-stream {\n  position: absolute;\n  width: 150%;\n  height: 150%;\n  top: -25%;\n  left: -25%;\n  pointer-events: none;\n  z-index: 6;\n  border-radius: 50%;\n  overflow: hidden;\n  mix-blend-mode: screen;\n  opacity: 0;\n  mask-image: radial-gradient(circle at center, rgba(0,0,0,1) 40%, transparent 72%);\n  -webkit-mask-image: radial-gradient(circle at center, rgba(0,0,0,1) 40%, transparent 72%);\n}\n\n.ff-prime-badge-wrap .ff-energy-beam {\n  position: absolute;\n  width: 130%;\n  height: 55%;\n  bottom: -20%;\n  right: -20%;\n  background: linear-gradient(\n    45deg,\n    transparent 15%,\n    rgba(255, 160, 0, 0.25) 38%,\n    rgba(255, 235, 130, 0.7) 48%,\n    rgba(255, 255, 255, 0.95) 52%,\n    rgba(255, 190, 40, 0.5) 56%,\n    transparent 78%\n  );\n  transform: rotate(-35deg);\n  filter: blur(5px);\n}\n\n/* Level 8 Energy Stream Animation */\n.ff-prime-lvl-8 .ff-energy-stream {\n  opacity: 1;\n}\n\n.ff-prime-lvl-8 .ff-energy-beam {\n  animation: ffEnergyFlowRightToUp 3.2s cubic-bezier(0.2, 0.8, 0.3, 1) infinite;\n}\n\n@keyframes ffEnergyFlowRightToUp {\n  0% {\n    transform: translate(65%, 65%) rotate(-35deg);\n    opacity: 0;\n  }\n  15% {\n    opacity: 0.95;\n  }\n  60% {\n    transform: translate(-45%, -45%) rotate(-35deg);\n    opacity: 0.85;\n  }\n  85%, 100% {\n    transform: translate(-85%, -85%) rotate(-35deg);\n    opacity: 0;\n  }\n}\n\n/* ========================================================\n   LEVEL-SPECIFIC EFFECTS CONFIGURATION (ZERO BG COLOR)\n   ======================================================== */\n\n/* Level 1, 2, 3: COMPLETELY STATIC (NO EFFECTS) */\n.ff-prime-lvl-1 .ff-badge-img,\n.ff-prime-lvl-2 .ff-badge-img,\n.ff-prime-lvl-3 .ff-badge-img {\n  filter: drop-shadow(0 2px 5px rgba(0, 0, 0, 0.35));\n  animation: none !important;\n}\n\n/* Level 4: Subtle Ambient Shine */\n.ff-prime-lvl-4 .ff-core-aura {\n  background: radial-gradient(circle, rgba(72, 202, 228, 0.3) 0%, transparent 68%);\n  opacity: 0.5;\n  animation: ffBreatheSubtle 3.8s ease-in-out infinite alternate;\n}\n.ff-prime-lvl-4 .ff-badge-img {\n  filter: drop-shadow(0 2px 8px rgba(0, 180, 216, 0.35));\n}\n@keyframes ffBreatheSubtle {\n  0% { transform: scale(0.95); opacity: 0.25; }\n  100% { transform: scale(1.1); opacity: 0.55; }\n}\n\n/* Level 5: Radiant Ambient Halo */\n.ff-prime-lvl-5 .ff-core-aura {\n  background: radial-gradient(circle, rgba(255, 183, 3, 0.35) 0%, transparent 70%);\n  opacity: 0.6;\n  animation: ffBreatheMedium 3.2s ease-in-out infinite alternate;\n}\n.ff-prime-lvl-5 .ff-badge-img {\n  animation: ffWingsPulseSoft 3.2s ease-in-out infinite alternate;\n  filter: drop-shadow(0 2px 10px rgba(255, 183, 3, 0.45));\n}\n@keyframes ffBreatheMedium {\n  0% { transform: scale(0.92); opacity: 0.35; }\n  100% { transform: scale(1.12); opacity: 0.65; }\n}\n@keyframes ffWingsPulseSoft {\n  0% { transform: scale(1); }\n  100% { transform: scale(1.02); }\n}\n\n/* Level 6: Amber Flame Aura */\n.ff-prime-lvl-6 .ff-core-aura {\n  background: radial-gradient(circle, rgba(255, 183, 3, 0.45) 0%, rgba(251, 133, 0, 0.2) 45%, transparent 70%);\n  opacity: 0.7;\n  animation: ffBreatheMedium 2.8s ease-in-out infinite alternate;\n}\n.ff-prime-lvl-6 .ff-badge-img {\n  animation: ffWingsPulseSoft 2.8s ease-in-out infinite alternate;\n  filter: drop-shadow(0 3px 12px rgba(251, 133, 0, 0.55));\n}\n\n/* Level 7: Mythic Grandmaster Aura */\n.ff-prime-lvl-7 .ff-core-aura {\n  background: radial-gradient(circle, rgba(255, 215, 0, 0.5) 0%, rgba(251, 133, 0, 0.25) 45%, transparent 72%);\n  opacity: 0.8;\n  animation: ffBreatheMythic 2.6s ease-in-out infinite alternate;\n}\n.ff-prime-lvl-7 .ff-gem-glint {\n  animation: ffGemSparkle 4.5s ease-in-out infinite;\n}\n.ff-prime-lvl-7 .ff-badge-img {\n  animation: ffWingsMythicSoft 2.6s ease-in-out infinite alternate;\n  filter: \n    drop-shadow(0 0 10px rgba(255, 215, 0, 0.65)) \n    drop-shadow(0 3px 12px rgba(0, 0, 0, 0.4));\n}\n@keyframes ffBreatheMythic {\n  0% { transform: scale(0.94); opacity: 0.45; }\n  100% { transform: scale(1.15); opacity: 0.85; }\n}\n@keyframes ffWingsMythicSoft {\n  0% { transform: scale(1) translateY(0); }\n  100% { transform: scale(1.025) translateY(-2px); }\n}\n\n/* Level 8: REFINED REALISTIC LEGENDARY (With Ascending Golden Beam + Subtle Flame) */\n.ff-prime-lvl-8 .ff-core-aura {\n  background: radial-gradient(circle, rgba(255, 235, 120, 0.5) 0%, rgba(255, 196, 0, 0.3) 40%, rgba(251, 133, 0, 0.15) 60%, transparent 75%);\n  opacity: 0.85;\n  animation: ffBreatheLegendarySoft 2.6s ease-in-out infinite alternate;\n}\n\n.ff-prime-lvl-8 .ff-gem-glint {\n  animation: ffGemSparkle 3.6s ease-in-out infinite;\n}\n\n@keyframes ffGemSparkle {\n  0%, 72% { opacity: 0; transform: translate(-50%, -50%) scale(0.2); }\n  82% { opacity: 0.95; transform: translate(-50%, -50%) scale(1.1); }\n  88% { opacity: 0.4; transform: translate(-50%, -50%) scale(1.3); }\n  96%, 100% { opacity: 0; transform: translate(-50%, -50%) scale(1.4); }\n}\n\n.ff-prime-lvl-8 .ff-badge-img {\n  animation: ffWingsLegendarySoft 2.6s ease-in-out infinite alternate;\n  filter: \n    drop-shadow(0 0 8px rgba(255, 235, 120, 0.85)) \n    drop-shadow(0 0 18px rgba(255, 196, 0, 0.6)) \n    drop-shadow(0 0 32px rgba(251, 133, 0, 0.3)) \n    drop-shadow(0 4px 10px rgba(0, 0, 0, 0.45));\n}\n\n@keyframes ffBreatheLegendarySoft {\n  0% { transform: scale(0.92); opacity: 0.45; }\n  100% { transform: scale(1.15); opacity: 0.85; }\n}\n\n@keyframes ffWingsLegendarySoft {\n  0% { \n    transform: scale(1) translateY(0); \n    filter: \n      drop-shadow(0 0 6px rgba(255, 235, 120, 0.75)) \n      drop-shadow(0 0 14px rgba(255, 196, 0, 0.5)) \n      drop-shadow(0 0 25px rgba(251, 133, 0, 0.2)) \n      drop-shadow(0 4px 10px rgba(0, 0, 0, 0.45));\n  }\n  100% { \n    transform: scale(1.025) translateY(-2px); \n    filter: \n      drop-shadow(0 0 10px rgba(255, 245, 160, 0.95)) \n      drop-shadow(0 0 22px rgba(255, 196, 0, 0.75)) \n      drop-shadow(0 0 38px rgba(251, 133, 0, 0.38)) \n      drop-shadow(0 5px 12px rgba(0, 0, 0, 0.5));\n  }\n}\n\n/* Profile Tag Shimmer (Transparent) */\n.ff-prime-profile-tag {\n  display: inline-block;\n  background: transparent !important;\n  vertical-align: middle;\n  filter: drop-shadow(0 0 6px rgba(255, 215, 0, 0.6));\n  animation: ffTagPulseSoft 2.5s infinite alternate;\n}\n@keyframes ffTagPulseSoft {\n  from { filter: drop-shadow(0 0 4px rgba(255, 196, 0, 0.4)); }\n  to { filter: drop-shadow(0 0 10px rgba(255, 235, 100, 0.8)); }\n}\n";
  if (!document.getElementById('ff-prime-styles')) {
    const styleEl = document.createElement('style');
    styleEl.id = 'ff-prime-styles';
    styleEl.textContent = css;
    document.head.appendChild(styleEl);
  }

  // 2. Embedded Authentic HD PNG Assets (Zero Server Requests)
  const BADGE_ASSETS = {"1": "data:image/png;base64,", "2": "data:image/png;base64,", "3": "data:image/png;base64,", "4": "data:image/png;base64,", "5": "data:image/png;base64,", "6": "data:image/png;base64,", "7": "data:image/png;base64,", "8": "data:image/png;base64,"};
  const PROFILE_TAG_SRC = "data:image/png;base64,";

  // 3. Core Badge Class
  class PrimeBadge {
    constructor(target, options) {
      options = options || {};
      this.container = typeof target === 'string' ? document.querySelector(target) : target;
      if (!this.container) return;

      this.level = Math.max(1, Math.min(8, parseInt(options.level) || 8));
      this.size = options.size || 'md';
      this.enableTilt = options.tilt !== undefined ? options.tilt : (this.size === 'lg' || this.size === 'xl');

      this.particles = [];
      this.animId = null;
      this.canvas = null;
      this.ctx = null;

      this.render();
    }

    render() {
      this.container.innerHTML = '';

      this.wrapper = document.createElement('div');
      const sizeClass = ['sm', 'md', 'lg', 'xl'].includes(this.size) ? ('ff-prime-' + this.size) : '';
      this.wrapper.className = 'ff-prime-badge-wrap ff-prime-lvl-' + this.level + ' ' + sizeClass;
      
      if (!sizeClass && this.size) {
        this.wrapper.style.width = this.size;
        this.wrapper.style.height = this.size;
      }

      // 1. Core Aura (Level 4 to 8)
      if (this.level >= 4) {
        const aura = document.createElement('div');
        aura.className = 'ff-core-aura';
        this.wrapper.appendChild(aura);
      }

      // 2. Particle Canvas (Level 6 to 8)
      if (this.level >= 6) {
        this.canvas = document.createElement('canvas');
        this.canvas.className = 'ff-particle-canvas';
        this.wrapper.appendChild(this.canvas);
        this.ctx = this.canvas.getContext('2d');
      }

      // 3. Badge Image
      this.img = document.createElement('img');
      this.img.src = BADGE_ASSETS[this.level.toString()] || BADGE_ASSETS['8'];
      this.img.alt = 'Free Fire Prime Level ' + this.level;
      this.img.className = 'ff-badge-img';
      this.wrapper.appendChild(this.img);

      // 4. Natural Gem Specular Glint (Levels 7 & 8)
      if (this.level >= 7) {
        const glint = document.createElement('div');
        glint.className = 'ff-gem-glint';
        this.wrapper.appendChild(glint);
      }

      // 5. Ascending Golden Energy Stream (Level 8 only: Right-to-Upward flowing beam)
      if (this.level >= 8) {
        const stream = document.createElement('div');
        stream.className = 'ff-energy-stream';
        const beam = document.createElement('div');
        beam.className = 'ff-energy-beam';
        stream.appendChild(beam);
        this.wrapper.appendChild(stream);
      }

      this.container.appendChild(this.wrapper);

      if (this.enableTilt) this.setupTilt();
      if (this.canvas) this.setupParticles();
    }

    setupTilt() {
      this.wrapper.addEventListener('mousemove', (e) => {
        const rect = this.wrapper.getBoundingClientRect();
        const x = e.clientX - rect.left - rect.width / 2;
        const y = e.clientY - rect.top - rect.height / 2;
        const rotateX = (-y / rect.height) * 16;
        const rotateY = (x / rect.width) * 16;
        this.img.style.transform = 'perspective(600px) rotateX(' + rotateX + 'deg) rotateY(' + rotateY + 'deg) scale(1.04)';
      });

      this.wrapper.addEventListener('mouseleave', () => {
        this.img.style.transform = 'perspective(600px) rotateX(0deg) rotateY(0deg) scale(1)';
      });
    }

    setupParticles() {
      const resize = () => {
        if (!this.canvas) return;
        this.canvas.width = this.wrapper.clientWidth * 1.8;
        this.canvas.height = this.wrapper.clientHeight * 1.8;
      };
      resize();

      const count = this.level === 8 ? 16 : (this.level === 7 ? 8 : 4);
      this.particles = [];
      for (let i = 0; i < count; i++) {
        this.particles.push(this.createParticle());
      }

      const animate = () => {
        if (!this.ctx || !this.canvas) return;
        this.ctx.clearRect(0, 0, this.canvas.width, this.canvas.height);

        const w = this.canvas.width;
        const h = this.canvas.height;

        this.particles.forEach(p => {
          p.y -= p.speedY;
          p.x += p.speedX + Math.sin(p.life * 0.08) * 0.3;
          p.life++;
          p.alpha = Math.max(0, 1 - (p.life / p.maxLife));

          if (p.life >= p.maxLife || p.y < 0) {
            Object.assign(p, this.createParticle());
          }

          this.ctx.save();
          this.ctx.beginPath();
          this.ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
          this.ctx.fillStyle = p.color + p.alpha + ')';
          this.ctx.shadowColor = p.color + '0.8)';
          this.ctx.shadowBlur = 6;
          this.ctx.fill();
          this.ctx.restore();
        });

        this.animId = requestAnimationFrame(animate);
      };

      animate();
    }

    createParticle() {
      const w = this.canvas ? this.canvas.width : 160;
      const h = this.canvas ? this.canvas.height : 160;
      const colors = ['rgba(255, 235, 120, ', 'rgba(255, 200, 50, ', 'rgba(255, 160, 20, '];
      return {
        x: (w / 2) + (Math.random() - 0.5) * (w * 0.38),
        y: (h * 0.58) + (Math.random() - 0.5) * (h * 0.2),
        size: Math.random() * (this.level === 8 ? 1.6 : 1.2) + 0.8,
        speedY: Math.random() * 1.0 + 0.5,
        speedX: (Math.random() - 0.5) * 0.6,
        life: Math.random() * 25,
        maxLife: Math.random() * 60 + 40,
        alpha: 1,
        color: colors[Math.floor(Math.random() * colors.length)]
      };
    }

    setLevel(lvl) {
      this.destroy();
      this.level = Math.max(1, Math.min(8, parseInt(lvl) || 8));
      this.render();
    }

    destroy() {
      if (this.animId) cancelAnimationFrame(this.animId);
      this.particles = [];
      this.container.innerHTML = '';
    }
  }

  // 4. Custom HTML Element: <ff-prime level="8" size="md"></ff-prime>
  if (window.customElements && !window.customElements.get('ff-prime')) {
    class FFPrimeElement extends HTMLElement {
      connectedCallback() {
        const level = this.getAttribute('level') || 8;
        const size = this.getAttribute('size') || 'md';
        this.badge = new PrimeBadge(this, { level: level, size: size });
      }
      static get observedAttributes() { return ['level', 'size']; }
      attributeChangedCallback(name, oldVal, newVal) {
        if (oldVal !== newVal && this.badge) {
          if (name === 'level') this.badge.setLevel(newVal);
        }
      }
    }
    window.customElements.define('ff-prime', FFPrimeElement);
  }

  // 5. Automatic Scanner for data-ff-prime elements
  function initAll() {
    document.querySelectorAll('[data-ff-prime]').forEach(el => {
      const level = el.getAttribute('data-ff-prime');
      const size = el.getAttribute('data-size') || 'md';
      new PrimeBadge(el, { level: level, size: size });
    });

    document.querySelectorAll('img.ff-prime-profile-tag:not([src])').forEach(img => {
      img.src = PROFILE_TAG_SRC;
    });
  }

  window.PrimeBadge = PrimeBadge;
  window.FF_PRIME_ASSETS = BADGE_ASSETS;
  window.FF_PROFILE_TAG = PROFILE_TAG_SRC;

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initAll);
  } else {
    initAll();
  }
})(typeof window !== 'undefined' ? window : this, document);
